(function() {
  var uzairImg = "data:image/webp;base64,";
  function setUzair() {
    var img = document.querySelector("#li-shot img");
    if (img) img.src = uzairImg;
  }
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", setUzair);
  } else {
    setUzair();
  }
})();
